/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, And, I, Implies, Mul, Not, Or, Pow, Q, Sym, abs, isUnsolved, mul, pi, rational, satask, symbols } from '../../src';
import { sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.assumptions.satask", () => {
  it("extract_predargs(props, assump)", () => {
    const [x, y] = symbols('x y');
    expect(sympyMatches(new Set([abs(mul(x, y)), x, y]), '{y, x, Abs(x*y)}')).toBe(true);
  });
  it("satask(Q.zero(Abs(x)), Q.zero(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(satask(Q.zero(abs(x)), Q.zero(x)))).toBe('True');
  });
  it("exprs", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new Set([mul(x, y)]))).toBe('{x*y}');
  });
  it("exprs (2)", () => {
    const [x, y] = symbols('x y');
    expect(sympyMatches(new Set([x, y]), '{y, x}')).toBe(true);
  });
  it("exprs (3)", () => {
    expect(sympyStr(new Set())).toBe('set()');
  });
});

